files.content:
.overlay {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 50%);
}

.dialog {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 320px;
  height: 200px;
  margin-top: -100px;
  margin-left: -160px;
  padding: 24px;
  background: #fff;
  border-radius: 8px;
}

assistant.body:
.overlay {
  position: fixed;
  inset: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgb(0 0 0 / 50%);
}

.dialog {
  width: 320px;
  padding: 24px;
  background: #fff;
  border-radius: 8px;
}

.overlay {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgb(0 0 0 / 50%);
}

.dialog {
  box-sizing: border-box;
  width: min(320px, 100% - 32px);
  padding: 24px;
  background: #fff;
  border-radius: 8px;
}
